namespace RT.BigInteger.Tests
{
    [TestClass]
    public sealed class TestBitwise
    {
        [TestMethod]
        public void TestGetBit()
        {
            var value = BigInt.Parse("40334178257864924323584572311515851078300593481");
            var bits = "100100101011011111101000111110101111011000011110110100101110101101111010011010100001000010100000010010001110111011010011111011010001010110100101000010001110000000";
            for (var bit = 0; bit < bits.Length; bit++)
                Assert.AreEqual(bits[bit] == '1', value.GetBit(bit));

            value = BigInt.Parse("-6781716271147111422738162164917835961947829721");
            bits = "111001000101001010101101011000111111000001001111101100001110000110000110110101001011110001000000111100010110111110000000011010001110110110100111111100110111111111";
            for (var bit = 0; bit < bits.Length; bit++)
                Assert.AreEqual(bits[bit] == '1', value.GetBit(bit));
        }

        private void testInvert(BigInt a, BigInt inverted)
        {
            Assert.AreEqual(inverted, ~a);
            Assert.AreEqual(inverted, a.Inverse);
        }

