        private void testLogicalOperators(BigInt a, BigInt b, BigInt orResult, BigInt andResult, BigInt xorResult)
        {
            Assert.AreEqual(orResult, a | b);
            Assert.AreEqual(andResult, a & b);
            Assert.AreEqual(xorResult, a ^ b);
        }

